 function restoreQueue(){claimQueue=null;try{const q=JSON.parse(storage?.getItem(queueKey(gateway.address))??'null');if(q&&same(q.who,gateway.address)&&Array.isArray(q.groups)&&q.groups.every(g=>Array.isArray(g.ids)&&g.ids.length<=32&&g.ids.every(id=>/^\d+$/.test(id))))claimQueue={...q,failed:q.failed??[],paused:true};}catch{} }
 let s={address:gateway.address,ready:false,contractsConfigured:!!(gateway.config.vault&&gateway.config.market),connectionTitle:gateway.config.vault&&gateway.config.market?'正在连接主网合约':'主网合约尚未部署',account:null,assets:[],orders:[],owned:[],inspection:null,inspectionLoading:false,inspectionError:'',discoveryState:gateway.address&&currentRoute()==='deposit'?'loading':'idle',discoveryProgress:'',discoveryError:'',reading:false,dataLoaded:false,bookLoaded:false,historyLoading:false,historyLoaded:false,referralLoaded:!gateway.referrals?.ready,chainTime:0,filter,buyOrderOnly:null,plan:planPurchase([],0n),quote:null,quoting:false,quoteError:'',readError:false,paused:false,trades:[],history:[],historyExhausted:false,historyError:false,rewardFresh:false,assetsComplete:true,ordersExhausted:false,stats:{loading:true,complete:false},dailyPer100:null,demo,explorer:gateway.config.explorer};
 startReadFeedback();
 const localization=initializeLocalization({onChange:()=>{render();renderTrust(gateway.config,{demo});}});renderTrust(gateway.config,{demo});
