 function modal(title,body,action=null,label='继续'){if($('transactions-modal').open)$('transactions-modal').close();modalAction=action;$('modal-content').innerHTML=`<div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button data-close aria-label="关闭">×</button></div><div class="modal-body">${body}</div><div class="modal-footer"><button class="button secondary" data-close>取消</button>${action?`<button class="button primary" data-modal-confirm>${esc(label)}</button>`:''}</div>`;localizeTree($('modal'));if(!$('modal').open)$('modal').showModal();}
 function close({cancelQueue=true}={}){if(txBusy&&!txSubmitted)return;preparation?.abort();preparation=null;previewBusy=false;$('modal').close();modalAction=null;if(cancelQueue&&claimQueue&&(claimQueue.groups.length||claimQueue.pendingHash||claimQueue.failed.length)){claimQueue.paused=true;saveQueue();s.claimProgress='已暂停，可继续未完成领取';render();}if(cancelQueue)cleanupQueue=null;}
 async function checkTransactions(){if(demo||!gateway.address||checkingTransactions||!journalFor(gateway.address).read().some(isPending))return;checkingTransactions=true;const who=gateway.address,journal=journalFor(who);let changed=false;try{for(const row of journal.read().filter(isPending)){const result=await gateway.checkTransaction(row);journal.put({...row,...result,note:result.note??'',checkedAt:Date.now()});s.transactionReadError='';if(!isPending(result))changed=true;if(gateway.address===who&&claimQueue?.pendingHash===row.hash&&!isPending(result)){if(result.status==='confirmed')completeClaimGroup(claimQueue,row.action?.ids??[]);else claimQueue.pendingHash=null;claimQueue.paused=true;saveQueue();}}}catch(e){if(gateway.address===who)s.transactionReadError=message(e);}finally{checkingTransactions=false;if(gateway.address===who){render();if(changed){refresh({fresh:true,book:currentRoute()==='market'});if(currentRoute()==='points')history();}}}}
 function replacementDialog(hash){const journal=journalFor(gateway.address),row=journal.read().find(t=>t.hash===hash);if(!row)return;modal('核对钱包中的替换交易','<p>仅填写同一钱包、同一 nonce 的加速或取消交易哈希。这里只查询链上结果，不发送交易。</p><label for="replacement-hash">替换交易哈希</label><input id="replacement-hash" placeholder="0x…64 位交易哈希">',async()=>{const replacementHash=$('replacement-hash').value.trim();if(!/^0x[0-9a-f]{64}$/i.test(replacementHash))throw Error('请填写完整交易哈希');const result=await gateway.checkTransaction({...row,replacementHash});journal.put({...row,...result,replacementHash,note:result.note??''});if(claimQueue?.pendingHash===hash&&!isPending(result)){if(result.status==='confirmed')completeClaimGroup(claimQueue,row.action?.ids??[]);else claimQueue.pendingHash=null;saveQueue();}close();await refresh();},'查询并更新');}
 function historyKey(who=gateway.address){return ['tapemicro-v2-history',gateway.config.chainId,gateway.config.vault,gateway.config.market,who].join('-').toLowerCase();}
 function loadHistoryCache(){try{s.history=JSON.parse(localStorage.getItem(historyKey())||'[]').map(t=>({...t,...(t.amount===undefined?{}:{amount:BigInt(t.amount)})}));}catch{s.history=[];}}
 function saveRecord(record,who){try{const key=historyKey(who),records=JSON.parse(localStorage.getItem(key)||'[]');records.unshift(record);localStorage.setItem(key,JSON.stringify(records.slice(0,30),(_,v)=>typeof v==='bigint'?String(v):v));if(same(gateway.address,who))loadHistoryCache();}catch{}}
 // Display the verified fixed-fee formula immediately. Fresh contract quotes
